  locationName: z.string().min(2, 'At least 2 characters').max(60),
  address: z.string().min(5, 'Enter a street address'),
  city: z.string().min(2, 'Required'),
  state: z.string().min(2, 'Required'),
  country: z.string().min(2, 'Required'),
  zip: z.string().min(3, 'Required'),
  phone: z.string().optional(),
})

type Step2Values = z.infer<typeof step2Schema>

interface StepFirstLocationProps {
  studioId: string | null
  onNext: () => void
  onBack: () => void
}

export function StepFirstLocation({
  studioId,
  onNext,
  onBack,
}: StepFirstLocationProps) {
  const supabase = createClient()
  const [saving, setSaving] = useState(false)

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<Step2Values>({
    resolver: zodResolver(step2Schema),
    defaultValues: {
      locationName: 'Main Studio',
      country: 'United States',
    },
  })

  async function onSubmit(data: Step2Values) {
    setSaving(true)
    try {
      if (!studioId) throw new Error('No studio found')

      const { error } = await supabase.from('locations').insert({
        studio_id: studioId,
        name: data.locationName,
        address: data.address,
        city: data.city,
        state: data.state,
        country: data.country,
        zip: data.zip,
        phone: data.phone ?? null,
      })
      if (error) throw error

      onNext()
    } catch (err) {
      toast.error(
        `Couldn't save — ${err instanceof Error ? err.message : 'Unknown error'}`,
      )
    } finally {
      setSaving(false)
    }
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
      <div>
        <h2 className="text-xl font-bold tracking-tight">
          Where are you located?
